#!/usr/bin/env python3
"""Run C2 Unit03 recalibration with target-safe margin and Arabic-only reader text."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c2_unit03.py')
text=SOURCE.read_text(encoding='utf-8')
replacements={
    'بعد perturbation':'بعد إزالة الاضطراب',
    'القيم الداخلية لا تعكس عمليات مستقلة':'القيم داخل النموذج لا تعكس عمليات مستقلة',
    'استخدم الفريق تجارب تدخلية تقيد بعض المعاملات':'استخدم الفريق تجارب تعتمد تغييرًا مقصودًا لتقييد بعض المعاملات',
}
for old,new in replacements.items():
    assert text.count(old)==1, old
    text=text.replace(old,new,1)
marker='UPDATES={'
assert text.count(marker)==1
EXTRA={
'ar-c2-u03-p01':"""وفي مراجعة مستقلة أعطت ندى الجداول لفريق لم يعرف أي وصف يفضله الباحثون الأصليون. طُلب منه تحديد الاختبار الأكثر قدرة على الفصل بين البديلين قبل رؤية النتائج. اختار الفريق أيضًا زمن الاستجابة لا الموضع النهائي، ما زاد الثقة بأن المعيار لم يُنتقَ فقط لخدمة نتيجة لاحقة. ثم سجلوا مسبقًا مقدار الفرق الذي سيعد مهمًا وما النتيجة التي ستبقي السؤال مفتوحًا. بهذه الخطوة صار عدم الحسم نفسه نتيجة محددة الشروط، لا فراغًا يسمح لكل طرف بإعلان أن نموذجه «لم يُدحض».""",
'ar-c2-u03-p02':"""وفي فحص ثان فصل الفريق بين خطأ المعايرة وخطأ الاستعمال. أعطوا مستخدمين مختلفين التعليمات نفسها ثم قارنوا مواضع التباين. اتضح أن جزءًا صغيرًا من الاختلاف يأتي من زمن الانتظار قبل القراءة، فأضيف شرط واضح إلى الإجراء. لم يعالج هذا الانحياز الرئيس لكنه منع سببًا آخر من الاختباء داخله. كما حفظ الفريق سجلًا للإصدارات يربط كل نتيجة بنسخة معادلة التحويل التي استُخدمت، حتى لا تختلط قياسات قديمة وجديدة في تحليل واحد من دون أن يعرف الباحث أن معنى الرقم تغيّر بين المرحلتين.""",
'ar-c2-u03-p03':"""ثم طلبت ليلى من الباحثين إعادة تحليل تجربة قديمة كانت ناجحة قرب الحد باستعمال قاعدة التوقف الجديدة. اكتشفوا أن القراءة السابقة كانت ستثير تنبيهًا مبكرًا لو كانت القاعدة موجودة حينها، لأن نقطتين متتاليتين أظهرتا انحرافًا صغيرًا تجاهله الفريق لصغر كل واحدة منفردة. لم يعد ذلك خطأً محرجًا يُخفى؛ استُخدم لتوضيح لماذا تحتاج شروط الاستخدام إلى معايير قابلة للتطبيق بأثر رجعي. كما ميزوا بين توسيع الثقة خطوة خطوة وبين تعديل النموذج ثم الادعاء أن المجال القديم والجديد اختبرا الشيء نفسه؛ كل تعديل يعيد فتح سؤال المعايرة ويحتاج إلى بيان مستقل.""",
'ar-c2-u03-p04':"""وفي تمرين مراجعة طلبت هناء من فريق آخر حذف أحد المتغيرات الثلاثة من النسخة الأبسط ورؤية ما الذي ينهار. لم يكن الهدف البحث عن أقل عدد بأي ثمن، بل معرفة وظيفة كل عنصر. حذف أحد المتغيرات غير شكل النمو في كل الحالات، بينما أمكن دمج عنصرين تحت شروط محدودة من دون خسارة كبيرة. دوّن الفريق الشرط الذي يسمح بالدمج، لأن التبسيط الذي يعمل فقط في نطاق ضيق يجب ألا ينتقل صامتًا إلى تجربة جديدة. صار لكل مستوى من التفصيل مبرر مرتبط بسؤال واختبار، لا مكانة أعلى لمجرد أنه أكثر واقعية أو أكثر اختصارًا.""",
'ar-c2-u03-p05':"""وفي مراجعة نهائية بنى الفريق سجلًا يوضح أي اختبار غيّر صياغة الادعاء فعلًا. بعض الخطوات رفعت الثقة في التنفيذ من دون تغيير النطاق، بينما أدت البيانات الجديدة إلى تضييق الفئة التي ينطبق عليها الاستنتاج. فصل هذا السجل بين «قوة الدليل داخل الادعاء» و«اتساع الادعاء نفسه». قد يصبح الاستنتاج أكثر قوة وأضيق في الوقت ذاته، وهي نتيجة أفضل من الاحتفاظ بعبارة عامة ضعيفة. كما طلبوا من كل مجموعة ذكر فشل محتمل لا يستطيع اختبارها الحالي كشفه، حتى يبقى معنى النجاح مرتبطًا بحدود التصميم لا بعدد المرات التي أعيد فيها العمل.""",
'ar-c2-u03-p06':"""وفي آخر المراجعة أعطت ندى الطلاب ادعاءً واحدًا ثم غيرت مصدر عدم اليقين في كل نسخة منه. مرة كان القياس نفسه منحازًا، ومرة كان التمثيل غير مميز بين آليتين، ومرة كانت المشكلة في نقل النتيجة إلى مجتمع جديد. بقيت الجملة السطحية متشابهة، لكن الاختبار المناسب تغير جذريًا. أظهر التمرين أن عبارة «نحتاج بيانات أكثر» لا تكفي؛ يجب معرفة أي بيانات، ولماذا ستضيف قدرة جديدة على الفصل أو التصحيح. عندما يستطيع الباحث تسمية المعلومة التي ستغير حكمه، يصبح التحفظ جزءًا من منطق الاكتشاف لا مجرد صيغة احتياطية.""",
}
extra_code="EXTRA = "+repr(EXTRA)+"\nfor _pid,_extra in EXTRA.items():\n    ADD[_pid]=ADD[_pid].rstrip()+' '+_extra.strip()\n"
patched=text.replace(marker,extra_code+'\n'+marker,1)
exec(compile(patched,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
